#include <bits/stdc++.h>
using namespace std;

using ll=long long;

const int N=10005, S=N-2, T=N-1;
const int M=2000010;
const int INF=2000000000;

int head[N], to[M], nxt[M], cap[M], cost[M], edge_id=1;

void add_edge(int u, int v, int capacity, int cst){
	to[++edge_id]=v; nxt[edge_id]=head[u]; head[u]=edge_id;
	cap[edge_id]=capacity; cost[edge_id]=cst;
	to[++edge_id]=u; nxt[edge_id]=head[v]; head[v]=edge_id;
	cap[edge_id]=0; cost[edge_id]=-cst;
}

queue<int> q;
long long dist[N];
bool in_queue[N];

bool spfa(){
	memset(in_queue, 0, sizeof(in_queue));
	memset(dist, 0x3f, sizeof(dist));
	q.push(T); dist[T]=0; in_queue[T]=true;
	while(!q.empty()){
		int x=q.front(); q.pop();
		in_queue[x]=false;
		for(int i=head[x];i;i=nxt[i]){
			int y=to[i];
			if(cap[i^1] && dist[y]>dist[x]+cost[i^1]){
				dist[y]=dist[x]+cost[i^1];
				if(!in_queue[y]){
					q.push(y);
					in_queue[y]=true;
				}
			}
		}
	}
	return dist[S]<1e18;
}

int dfs(int x, int flow_limit, ll &total_cost){
	int flow=0; in_queue[x]=true;
	if(x==T) return flow_limit;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(!cap[i] || in_queue[y]) continue;
		if(dist[x]!=dist[y]+cost[i]) continue;
		int t=dfs(y, min(cap[i], flow_limit - flow), total_cost);
		cap[i]-=t; cap[i^1]+=t;
		flow+=t; total_cost+=t*cost[i];
		if(flow==flow_limit) break;
	}
	return flow;
}

long long min_cost_flow(){
	int total_flow=0; ll total_cost=0;
	while(spfa()){
		memset(in_queue, 0, sizeof(in_queue));
		total_flow+=dfs(S, 101, total_cost);
	}
	return total_cost;
}

int main(){
	int n,m,k,c,d,limit=101;
	cin>>n>>m>>k>>c>>d;
	for(int i=0;i<k;i++){
		int x; cin>>x; x--;
		add_edge(S,x,1,0);
	}
	for(int i=0;i<limit;i++)
		add_edge(i*n,T,k,c*i);
	for(int i=0;i<n;i++)
		for(int j=0;j<limit-1;j++)
			add_edge(i+j*n,i+(j+1)*n,k,0);
	while(m--){
		int x,y; cin>>x>>y; x--; y--;
		for(int i=0;i<limit-1;i++)
			for(int j=k-1;j>=0;j--){
				add_edge(x+i*n,y+(i+1)*n,1,d*(j*2+1));
				add_edge(y+i*n,x+(i+1)*n,1,d*(j*2+1));
			}
	}
	cout<<min_cost_flow();
	return 0;
}
